/* rpc_start_throwing (session-bound):
 *   entity                   int, 15 bits, 0..32767
 *   arg1                     up to 48 x u64
 *   unsigned_value           int, 32 bits, 0..0
 */
#define HF_RPC_START_THROWING 0x04D75D0Bu
typedef struct HfRpc_start_throwing
{
    int32_t entity;
    uint32_t arg1_count;
    uint64_t arg1[48];
    int32_t unsigned_value;
} HfRpc_start_throwing;
static inline int hf_rpc_start_throwing_read(const HfRpcEvent* e, HfRpc_start_throwing* out)
{
    uint32_t at = 0;
    if (e->rpc != HF_RPC_START_THROWING) return 1;
    {
        const void* v = hf_rpc_take_(e, &at, 1u);
        if (v == NULL) return 1;
        out->entity = *(const int32_t*)v;
    }
    out->arg1_count = hf_rpc_take_count_(e, &at, 48u);
    if (out->arg1_count == 0xFFFFFFFFu) return 1;
    for (uint32_t i = 0; i < out->arg1_count; i++)
    {
        const void* v = hf_rpc_take_(e, &at, 9u);
        if (v == NULL) return 1;
        out->arg1[i] = *(const uint64_t*)v;
    }
    {
        const void* v = hf_rpc_take_(e, &at, 1u);
        if (v == NULL) return 1;
        out->unsigned_value = *(const int32_t*)v;
    }
    return at == e->count ? 0 : 1;
}
static inline int hf_rpc_start_throwing_send(HfMod* mod, uint64_t to, const HfRpc_start_throwing* in)
{
    HfRpcArg a[51];
    uint32_t n = 0;
    a[n].kind = 1u; a[n].size = (uint32_t)sizeof in->entity; a[n].value = &in->entity; n++;
    if (in->arg1_count > 48u) return 1;
    a[n].kind = HF_RPC_KIND_ARRAY; a[n].size = 0; a[n].value = (const void*)(uintptr_t)in->arg1_count; n++;
    for (uint32_t i = 0; i < in->arg1_count; i++)
    {
        a[n].kind = 9u; a[n].size = (uint32_t)sizeof in->arg1[i]; a[n].value = &in->arg1[i]; n++;
    }
    a[n].kind = 1u; a[n].size = (uint32_t)sizeof in->unsigned_value; a[n].value = &in->unsigned_value; n++;
    return hf_rpc_send_(mod, HF_RPC_START_THROWING, to, a, n);
}

